\title{A Cross-Domain Bridge for the $\sqrt{2}$ Threshold:\\
Vietoris--Rips Complexes, Extremal Graph Theory,\\ and Information Theory}
\author{Aristotle}
\date{2026-07-13}

\begin{document}
\maketitle

\begin{abstract}
The Vietoris--Rips complex is the central combinatorial object of topological
data analysis, but its size can grow as $2^n$ in the number $n$ of data points,
making faithful representation and approximation a fundamental computational
concern. We give a self-contained account of why, below the multiplicative
threshold $c = \sqrt{2}$, this exponential blow-up is unavoidable, by aligning
three classically distinct viewpoints on a single extremal object: the
equidistant configuration realized by the $n$ standard basis vectors of Euclidean
space, whose pairwise distances all equal $\sqrt{2}$. First, we establish the
\emph{clique dictionary}: the Vietoris--Rips complex at scale $r$ equals the
clique complex of the proximity graph at scale $r$. Second, we invoke the
\emph{extremal bound}: a graph on $n$ vertices has at most $2^n$ cliques, with
equality exactly for the complete graph. Third, we translate the count into an
\emph{information-theoretic floor}: a family of $M$ objects requires $\lceil
\log_2 M\rceil$ addressing bits, so a level of $2^n$ simplices requires $n$ bits.
Combining these, every multiplicative $c$-approximation of the equidistant
Vietoris--Rips filtration has a level with at least $2^n$ simplices, hence
requiring at least $n$ bits of storage. The sharp exponent is $\gamma(c) =
\tfrac12 - \log_2 c$, strictly positive on the entire regime $1 \le c < \sqrt{2}$
and vanishing exactly at $c = \sqrt{2}$.
\end{abstract}

\section{Introduction}

Topological data analysis (TDA) extracts qualitative, multi-scale shape
information from finite metric data. Its principal construction is the
\emph{Vietoris--Rips filtration}, a nested family of simplicial complexes indexed
by a scale parameter. Because the Vietoris--Rips complex of $n$ points can
contain up to $2^n$ simplices, much work seeks smaller structures that preserve
persistent homology up to a controlled multiplicative distortion $c \ge 1$ of the
scale.

We present a clean, fully explicit lower bound. On the equidistant configuration,
no $c$-approximation with $1 \le c < \sqrt{2}$ can avoid a level of $2^n$
simplices, hence a description-length cost of $n$ bits. The number $\sqrt{2}$ is
the exact pairwise distance of the $n$ standard basis vectors, the canonical
Euclidean realization of an equidistant point set. Our contribution is the
\emph{bridge}: the argument threads through three subjects, and the equidistant
configuration is exactly where all three attain their extremes simultaneously.

\section{Definitions}

Throughout, $n \in \mathbb{N}$ and the point set is $\{0,1,\dots,n-1\}$. A
\emph{dissimilarity} is a function $D : \{0,\dots,n-1\}^2 \to \mathbb{R}$.

\begin{definition}[Vietoris--Rips simplex and complex]
A subset $S$ is a \emph{Vietoris--Rips simplex at scale $r$} if $D(i,j) \le r$ for
all $i,j \in S$. The \emph{Vietoris--Rips complex} is
\[
\VR(D,r) = \{\, S \subseteq \{0,\dots,n-1\} : \forall i,j \in S,\ D(i,j) \le r \,\}.
\]
\end{definition}

\begin{definition}[Equidistant dissimilarity]
For $d \in \mathbb{R}$, let $\eqd_d(i,i) = 0$ and $\eqd_d(i,j) = d$ for $i \ne j$.
For $d = \sqrt{2}$ this is realized isometrically by the standard basis vectors
$e_0,\dots,e_{n-1}$ in $\mathbb{R}^n$, since $\lVert e_i - e_j\rVert = \sqrt{2}$
for $i \ne j$.
\end{definition}

\begin{definition}[Proximity graph]
The \emph{proximity graph} $\Gph(D,r)$ has vertex set $\{0,\dots,n-1\}$, with
distinct $i,j$ adjacent iff $D(i,j) \le r$ and $D(j,i) \le r$.
\end{definition}

\begin{definition}[Clique complex]
For a simple graph $H$, its \emph{clique complex} is
$\Cl(H) = \{ S \subseteq V(H) : S \text{ is a clique of } H \}$.
\end{definition}

\begin{definition}[Multiplicative $c$-approximation]
A family $G : \mathbb{R} \to \{\text{complexes}\}$ is a \emph{$c$-approximation}
of $\VR(D,\cdot)$ if $c \ge 1$ and, for all $t \ge 0$,
\[
\VR(D,t) \subseteq G(ct) \qquad\text{and}\qquad G(t) \subseteq \VR(D,ct).
\]
\end{definition}

\begin{definition}[Bit complexity]
For a finite family $F$, $\bits(F) = \lceil \log_2 |F| \rceil$, the number of bits
needed to give each member a distinct binary address.
\end{definition}

\section{The Clique Dictionary (Geometry $\leftrightarrow$ Graph Theory)}

\begin{theorem}[Clique dictionary]\label{thm:dict}
Let $D$ be a dissimilarity and $r \in \mathbb{R}$ with $D(i,i) \le r$ for all $i$.
Then $\VR(D,r) = \Cl(\Gph(D,r))$.
\end{theorem}

\begin{proof}[Proof sketch]
If $S \in \VR(D,r)$, distinct $i,j \in S$ satisfy $D(i,j),D(j,i) \le r$, so they
are adjacent; hence $S$ is a clique. Conversely, a clique has all distinct pairs
adjacent, giving $D(i,j) \le r$; the diagonal case $i=j$ uses $D(i,i) \le r$.
\end{proof}

\section{The Extremal Bound (Graph Theory)}

\begin{theorem}[Clique-count ceiling]\label{thm:ceiling}
Every graph $H$ on $n$ vertices satisfies $|\Cl(H)| \le 2^n$.
\end{theorem}

\begin{proof}[Proof sketch]
Every clique is a subset of the $n$-vertex set, and there are $2^n$ subsets.
\end{proof}

\begin{theorem}[Maximizer]\label{thm:max}
For the complete graph $K_n$, every subset is a clique, so $\Cl(K_n) =
\Pow(\{0,\dots,n-1\})$ with $|\Cl(K_n)| = 2^n$; hence $|\Cl(H)| \le |\Cl(K_n)|$
for every $n$-vertex graph $H$.
\end{theorem}

\begin{proof}[Proof sketch]
In $K_n$ all distinct pairs are adjacent, so every subset is a clique; thus
$\Cl(K_n)$ is the full power set. Combine with Theorem~\ref{thm:ceiling}.
\end{proof}

\section{The Equidistant Configuration Is Extremal}

\begin{theorem}[Equidistant proximity graph is complete]\label{thm:eqtop}
If $d \le r$, then $\Gph(\eqd_d, r) = K_n$.
\end{theorem}

\begin{proof}[Proof sketch]
For distinct $i,j$, $\eqd_d(i,j) = \eqd_d(j,i) = d \le r$, so every distinct pair
is adjacent; adjacency also requires distinctness. Hence the graph is complete.
\end{proof}

\begin{corollary}[Exponential count]\label{cor:count}
If $0 \le d \le r$, then $\VR(\eqd_d, r) = \Pow(\{0,\dots,n-1\})$ and
$|\VR(\eqd_d, r)| = 2^n$.
\end{corollary}

\begin{proof}[Proof sketch]
For any subset $S$ and $i,j \in S$, $\eqd_d(i,j)$ is $0$ or $d \le r$, hence $\le
r$; so every subset is a simplex. Equivalently combine
Theorems~\ref{thm:dict}, \ref{thm:eqtop}, \ref{thm:max}. The count is $2^n$.
\end{proof}

\section{The Information-Theoretic Floor}

\begin{lemma}[Sufficiency of $\bits$]\label{lem:suff}
For every finite family $F$, $\;|F| \le 2^{\bits(F)}$.
\end{lemma}

\begin{proof}[Proof sketch]
This is the defining property of the ceiling logarithm: $M \le 2^{\lceil \log_2
M\rceil}$.
\end{proof}

\begin{lemma}[Lower bound on bits]\label{lem:nec}
If a finite family $F$ satisfies $2^k \le |F|$, then $k \le \bits(F)$.
\end{lemma}

\begin{proof}[Proof sketch]
From $2^k \le |F| \le 2^{\bits(F)}$ and strict monotonicity of $m \mapsto 2^m$,
we get $k \le \bits(F)$.
\end{proof}

\section{The Lower Bound and the Bridge Theorem}

\begin{theorem}[Simplex lower bound]\label{thm:simp}
Let $d \ge 0$ and $G$ be a $c$-approximation of $\VR(\eqd_d,\cdot)$. Then $2^n \le
|G(cd)|$.
\end{theorem}

\begin{proof}[Proof sketch]
The interleaving at $t=d$ gives $\VR(\eqd_d,d) \subseteq G(cd)$; monotonicity of
cardinality and Corollary~\ref{cor:count} (with $r=d$) give $2^n \le |G(cd)|$.
\end{proof}

\begin{theorem}[Bit lower bound]\label{thm:bit}
Under the hypotheses of Theorem~\ref{thm:simp}, $n \le \bits(G(cd))$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply Lemma~\ref{lem:nec} with $k=n$, $F=G(cd)$, using Theorem~\ref{thm:simp}.
\end{proof}

\begin{theorem}[Cross-domain bridge for the $\sqrt2$ threshold]\label{thm:bridge}
Fix $c$ with $1 \le c < \sqrt{2}$, and let $G$ be a $c$-approximation of
$\VR(\eqd_{\sqrt2},\cdot)$ on $n$ points. Then:
\begin{enumerate}
\item \emph{(Geometry $\leftrightarrow$ graph theory.)}
  $\VR(\eqd_{\sqrt2}, \sqrt2) = \Cl(K_n)$.
\item \emph{(Extremal graph theory.)} $|\Cl(K_n)| = 2^n$, and $|\Cl(H)| \le 2^n$
  for every $n$-vertex graph $H$.
\item \emph{(Information theory.)} $n \le \bits(G(c\sqrt2))$.
\item \emph{(Sharp exponent.)} $\gamma(c) = \tfrac12 - \log_2 c > 0$ throughout
  $1 \le c < \sqrt2$.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
Part (1) combines Theorem~\ref{thm:dict} (valid since $\eqd_{\sqrt2}(i,i) = 0 \le
\sqrt2$) with Theorem~\ref{thm:eqtop} at $d=r=\sqrt2$. Part (2) is
Theorems~\ref{thm:max} and \ref{thm:ceiling}. Part (3) is Theorem~\ref{thm:bit}
at $d=\sqrt2$. Part (4): $\gamma(c) > 0 \iff \log_2 c < \tfrac12 = \log_2 \sqrt2
\iff c < \sqrt2$.
\end{proof}

\section{Discussion}

The number $2^n$ appears three times: as the \emph{maximum} clique count over all
$n$-vertex graphs (Theorem~\ref{thm:ceiling}), uniquely achieved by $K_n$; as the
\emph{count} of simplices in the equidistant complex at scale $\sqrt2$
(Corollary~\ref{cor:count}); and as an \emph{exponential of a bit cost}, since
$2^n$ addressable objects require $n$ bits (Lemma~\ref{lem:nec}). The equidistant
configuration is the unique geometric object whose proximity graph is the extremal
graph, whose complex hits the extremal count, and whose level carries maximal
irreducible bit content. The $\sqrt2$ threshold is where these extremes lock
together, and where $\gamma(c) = \tfrac12 - \log_2 c$ crosses zero.

\section{Applications}

The bound certifies that any approximation claiming faithfulness better than a
$\sqrt2$ stretch cannot give worst-case sub-exponential size; the equidistant
cloud is a compact, explicit hard instance for benchmarking; and the clique
dictionary imports extremal-graph-theoretic results into TDA, with the
bit-complexity reading connecting complex size to coding cost.

\section{Future Directions}

\begin{enumerate}
\item \textbf{Homological refinement.} Replace the interleaving of complexes by an
  interleaving of persistence modules and derive the bound at the level of
  barcodes / interleaving distance.
\item \textbf{Beyond the equidistant instance.} Construct families (spherical
  codes, or perturbed simplices realizing Jung's constant $\sqrt{2n/(n+1)} \to
  \sqrt2$) whose optimal approximation size is genuinely $2^{\gamma(c)\,n}$ with
  $\gamma(c) \to 0$.
\item \textbf{Quantitative extremal graph theory.} Strengthen the clique-count
  ceiling to the Moon--Moser / Kruskal--Katona regime, bounding clique counts by
  edge counts or forbidden subgraphs.
\item \textbf{Entropic information theory.} Upgrade worst-case bit complexity to a
  Shannon-entropy statement: the uniform distribution over the $2^n$ simplices has
  entropy exactly $n$ bits.
\end{enumerate}

\section{Conclusion}

Below the $\sqrt2$ threshold, the exponential size of the Vietoris--Rips
filtration is a law, visible from geometry, graph theory, and information theory
at once. The equidistant configuration of $n$ points at mutual distance $\sqrt2$
is the single object where all three subjects reach their extremes together, and
$\gamma(c) = \tfrac12 - \log_2 c$ measures exactly how much room compression has:
none, until the stretch reaches $\sqrt2$.

