from itertools import combinations
from typing import Dict, FrozenSet, List, Set, Tuple
import math

def equidistant(n: int, d: float) -> Dict[Tuple[int, int], float]:
    """Equidistant dissimilarity on {0,...,n-1}: 0 on diagonal, d off it."""
    return {(i, j): (0.0 if i == j else d) for i in range(n) for j in range(n)}

def all_subsets(n: int) -> List[FrozenSet[int]]:
    return [frozenset(c) for k in range(n + 1) for c in combinations(range(n), k)]

def vr_complex(D: Dict[Tuple[int, int], float], r: float, n: int) -> List[FrozenSet[int]]:
    """Vietoris-Rips complex: subsets whose every pair is within r."""
    return [S for S in all_subsets(n) if all(D[(i, j)] <= r for i in S for j in S)]

def prox_edges(D: Dict[Tuple[int, int], float], r: float, n: int) -> Set[FrozenSet[int]]:
    return {frozenset((i, j)) for i in range(n) for j in range(n)
            if i != j and D[(i, j)] <= r and D[(j, i)] <= r}

def clique_complex(edges: Set[FrozenSet[int]], n: int) -> List[FrozenSet[int]]:
    return [S for S in all_subsets(n)
            if all(frozenset((i, j)) in edges for i, j in combinations(sorted(S), 2))]

def verify_dictionary(n: int) -> bool:
    """Confirm VR complex == clique complex of the proximity graph at scale sqrt(2)."""
    D = equidistant(n, math.sqrt(2))
    r = math.sqrt(2)
    return set(vr_complex(D, r, n)) == set(clique_complex(prox_edges(D, r, n), n))

if __name__ == "__main__":
    for n in range(1, 8):
        print(f"n={n}: VR == clique complex? {verify_dictionary(n)}; "
              f"size = 2^{n} = {2**n}")

import math
from typing import List, Tuple

def bit_complexity(size: int) -> int:
    """Minimum bits to give each of `size` objects a distinct address."""
    return 0 if size <= 1 else math.ceil(math.log2(size))

def approximation_floor(n: int) -> Tuple[int, int]:
    """For the equidistant cloud on n points, return (#simplices, #bits)
    that ANY c-approximation with c < sqrt(2) must pay at some level."""
    simplices = 2 ** n
    return simplices, bit_complexity(simplices)

def table(n_max: int) -> List[Tuple[int, int, int, bool]]:
    rows = []
    for n in range(1, n_max + 1):
        s, b = approximation_floor(n)
        rows.append((n, s, b, b == n))
    return rows

if __name__ == "__main__":
    print(f"{'n':>3} {'#simplices':>12} {'bits':>6} {'bits==n':>8}")
    for n, s, b, ok in table(20):
        print(f"{n:>3} {s:>12} {b:>6} {str(ok):>8}")

import math
from typing import List, Tuple

def gamma(c: float) -> float:
    """Sharp exponent governing the sqrt(2) threshold: gamma(c) = 1/2 - log2(c)."""
    return 0.5 - math.log2(c)

def positive_region(cs: List[float]) -> List[Tuple[float, float, bool]]:
    """gamma(c) > 0 exactly on [1, sqrt(2)); it vanishes at c = sqrt(2)."""
    return [(c, gamma(c), gamma(c) > 1e-12) for c in cs]

def cost_exponent(c: float, n: int) -> float:
    """Predicted worst-case size exponent 2^(gamma(c)*n) as a base-2 log."""
    return gamma(c) * n

if __name__ == "__main__":
    grid = [1.0, 1.1, 1.2, 1.25, 1.3, 1.35, 1.4, math.sqrt(2), 1.45, 1.5]
    print(f"{'c':>9} {'gamma(c)':>12} {'positive?':>10}")
    for c, g, pos in positive_region(grid):
        print(f"{c:>9.5f} {g:>12.6f} {str(pos):>10}")
    print(f"\nAt n=50, c=1.2: log2(worst-case size) >= {cost_exponent(1.2, 50):.2f}")

