from itertools import combinations
from typing import Callable, FrozenSet, List

def vietoris_rips_via_cliques(
    dist: Callable[[int, int], float], n: int, r: float
) -> List[FrozenSet[int]]:
    """Build the Vietoris-Rips complex at scale r as the clique complex of the
    proximity graph, exploiting the flag-complex identity.

    Complexity: building the edge set is O(n^2) distance calls; enumerating
    cliques is output-sensitive but worst-case O(2^n) (attained by the complete
    graph, i.e. the equidistant configuration)."""
    # 1. Proximity graph edges.
    adj = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            close = dist(i, j) <= r and dist(j, i) <= r
            adj[i][j] = adj[j][i] = close
    # 2. Cliques = subsets all of whose pairs are edges.
    cliques: List[FrozenSet[int]] = []
    for k in range(n + 1):
        for combo in combinations(range(n), k):
            if all(adj[a][b] for a, b in combinations(combo, 2)):
                cliques.append(frozenset(combo))
    return cliques

import math

def min_bits(family_size: int) -> int:
    """Minimum bits to address `family_size` distinct objects: ceil(log2 size).

    This is the information-theoretic floor: it satisfies both
    size <= 2^min_bits (sufficiency) and, if 2^k <= size, then k <= min_bits
    (necessity). Complexity: O(1)."""
    if family_size <= 1:
        return 0
    return math.ceil(math.log2(family_size))

def bits_from_pow(k: int) -> int:
    """When the family has exactly 2^k members the floor equals k."""
    return min_bits(2 ** k)
